import{_ as e,r as n,o,c,e as s,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const h=JSON.parse('{"title":"分页 - October CMS - 3.x","titleTemplate":false,"description":"了解如何显示分页链接。","frontmatter":{"subtitle":"了解如何显示分页链接。"},"headers":[{"level":2,"title":"分页数据","slug":"分页数据","link":"#分页数据","children":[{"level":3,"title":"多个分页实例","slug":"多个分页实例","link":"#多个分页实例","children":[]},{"level":3,"title":"使用自定义分页标记","slug":"使用自定义分页标记","link":"#使用自定义分页标记","children":[]}]},{"level":2,"title":"AJAX 分页","slug":"ajax-分页","link":"#ajax-分页","children":[]},{"level":2,"title":"加载更多分页","slug":"加载更多分页","link":"#加载更多分页","children":[{"level":4,"title":"参见","slug":"参见","link":"#参见","children":[]}]}],"relativePath":"3.x/zh-cn/cms/features/pagination.md","filePath":"3.x/zh-cn/cms/features/pagination.md"}'),u={name:"3.x/zh-cn/cms/features/pagination.md"};function k(g,a,r,d,m,v){const t=n("pre-heading"),p=n("post-heading");return o(),c("div",null,[s(t),a[0]||(a[0]=l("h1",null,"分页",-1)),s(p),a[1]||(a[1]=i(`<p>October CMS 内置了分页功能，它与标准模板集成并提供完全灵活的自定义标记。分页记录与<a href="./../../extend/database/pagination.html">模型分页查询</a>和 <a href="./../../markup/function/pager.html"><code>pager()</code> Twig 函数</a>紧密集成。</p><h2 id="分页数据"><a href="#分页数据" class="header-anchor">#</a> 分页数据</h2><p>分页数据集可以来自<a href="./../../extend/cms-components.html">组件逻辑</a>、页面或布局的 <a href="./../themes/themes.html">PHP 部分</a>，或来自 <a href="./../tailor/components.html">Tailor 组件</a>。以下是一个页面从 Tailor 组件请求分页数据的示例，每页 <strong>10</strong> 条记录。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">collection</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Post</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> posts <span class="token operator">=</span> collection<span class="token punctuation">.</span>paginate<span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>现在 <code>posts</code> 变量已可用。我们可以遍历每条记录并显示分页链接。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> post <span class="token operator">in</span> posts <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h2</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h2</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>nav</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> pager<span class="token punctuation">(</span>posts<span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>nav</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h3 id="多个分页实例"><a href="#多个分页实例" class="header-anchor">#</a> 多个分页实例</h3><p>默认情况下，分页会从 <code>?page</code> 查询字符串获取当前页码，因此在显示两个或更多分页数据集时会使用相同的页码。要解决此问题，请使用 <code>paginateCustom</code> 方法并指定唯一的参数名称。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">collection blog</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Post</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">collection category</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Category</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> posts <span class="token operator">=</span> blog<span class="token punctuation">.</span>paginateCustom<span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">,</span> <span class="token string"><span class="token punctuation">&#39;</span>postPage<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> comments <span class="token operator">=</span> comments<span class="token punctuation">.</span>paginateCustom<span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">,</span> <span class="token string"><span class="token punctuation">&#39;</span>commentPage<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>设置 <code>withQuery</code> 选项以保留其他分页实例的页码（可选）。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> pager<span class="token punctuation">(</span>categories<span class="token punctuation">,</span> <span class="token punctuation">{</span> withQuery<span class="token punctuation">:</span> <span class="token boolean">true</span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>这将使查询字符串包含两个页码，例如，<br><code>?postPage=1&amp;commentPage=2</code>。</p><h3 id="使用自定义分页标记"><a href="#使用自定义分页标记" class="header-anchor">#</a> 使用自定义分页标记</h3><p>要使用自定义分页标记，请从以下文件位置开始，将内容复制到你主题中的一个部件中。</p><div class="table"><table tabindex="0"><thead><tr><th>模板</th><th>详情</th></tr></thead><tbody><tr><td><code>default</code></td><td>渲染默认分页模板。<br>位置：<code>~/modules/system/views/pagination/default.htm</code></td></tr><tr><td><code>simple</code></td><td>渲染仅包含上一页和下一页按钮的分页。<br>位置：<code>~/modules/system/views/pagination/simple.htm</code></td></tr><tr><td><code>ajax</code></td><td>渲染 AJAX 分页记录。<br>位置：<code>~/modules/system/views/pagination/ajax.htm</code></td></tr></tbody></table></div><p>然后通过将 <code>partial</code> 选项传递给 pager 来渲染为部件。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> pager<span class="token punctuation">(</span>records<span class="token punctuation">,</span> <span class="token punctuation">{</span> partial<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>my-custom-pagination<span class="token punctuation">&#39;</span></span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><h2 id="ajax-分页"><a href="#ajax-分页" class="header-anchor">#</a> AJAX 分页</h2><p>使用 <code>ajaxPager()</code> Twig 函数通过 AJAX 动态更新分页记录。部件应显示记录并在内部包含 pager，例如，一个名为 <strong>latest-posts.htm</strong> 的部件包含以下内容。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> post <span class="token operator">in</span> posts <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h2</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h2</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>nav</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> ajaxPager<span class="token punctuation">(</span>posts<span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>nav</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>然后使用 <a href="./../../markup/tag/ajax-partial.html"><code>{% ajaxPartial %}</code> Twig 标签</a>在页面上渲染该部件。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">collection blog</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Post</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> posts <span class="token operator">=</span> blog<span class="token punctuation">.</span>paginate<span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h3</span><span class="token punctuation">&gt;</span></span>Latest Posts<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h3</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">ajaxPartial</span> <span class="token string"><span class="token punctuation">&#39;</span>latest-posts<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>或者，你可以将所有逻辑封装在部件内部，使其完全可移植。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">collection blog</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Post</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> posts <span class="token operator">=</span> blog<span class="token punctuation">.</span>paginate<span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> post <span class="token operator">in</span> posts <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h2</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h2</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>nav</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> ajaxPager<span class="token punctuation">(</span>posts<span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>nav</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>然后可以在任何页面或布局上渲染该部件，无需任何额外配置。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">ajaxPartial</span> <span class="token string"><span class="token punctuation">&#39;</span>latest-posts<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><h2 id="加载更多分页"><a href="#加载更多分页" class="header-anchor">#</a> 加载更多分页</h2><p>加载更多按钮，有时称为无限加载器，是一种以堆叠方式显示记录而非跨多页显示的方法。</p><p>此方法使用 AJAX 部件追加新内容以及一个自销毁按钮。例如，一个名为 <strong>load-more-posts.htm</strong> 的部件包含以下内容。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> posts <span class="token operator">=</span> blog<span class="token punctuation">.</span>paginate<span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> post <span class="token operator">in</span> posts <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h2</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h2</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> posts<span class="token punctuation">.</span>hasMorePages <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
        <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onAjax<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ _self: &#39;@&#39; }<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-request-success</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>this.remove()<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-request-data</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ page: <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> posts<span class="token punctuation">.</span>currentPage <span class="token operator">+</span> <span class="token number">1</span> <span class="token delimiter punctuation">}}</span></span> }<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-attach-loading</span><span class="token punctuation">&gt;</span></span>
        Load More
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>按钮元素利用 AJAX 数据属性的组合来执行<a href="./../ajax/update-partials.html">追加模式的自更新</a>，将下一页码作为数据传递，并在完成后移除自身。</p><p>该部件应使用 <a href="./../../markup/tag/ajax-partial.html"><code>{% ajaxPartial %}</code> Twig 标签</a>渲染。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">ajaxPartial</span> <span class="token string"><span class="token punctuation">&#39;</span>load-more-posts<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><h4 id="参见"><a href="#参见" class="header-anchor">#</a> 参见</h4><div class="custom-block also"><ul><li><a href="./../../extend/database/pagination.html">模型分页</a></li><li><a href="./../../markup/function/pager.html">Pager Twig 函数</a></li></ul></div>`,35))])}const x=e(u,[["render",k]]);export{h as __pageData,x as default};
